/* TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Tom; Brendon (integrator) added hard-tune mode for the Autotune (30 Oct 2026, with an AI coding assistant). */
/*
 * Pitch shifter: makes the sound higher or lower by a ratio (2 = an octave
 * higher, 0.5 = an octave lower) while it keeps its speed and length.
 * Samples are 16-bit PCM (plain signed sample values) at 48 kHz.
 * Pure C (no HAL, no RTOS); the caller owns the state. No task of its own:
 * the Autotune, Pitch up and Pitch down effects call it (audio_effects.c),
 * inside FxRenderTask while it makes an effect file. pitch_shifter.c
 * explains the method: a delay line read by two crossfaded heads (grains).
 */
#ifndef PITCH_SHIFTER_H
#define PITCH_SHIFTER_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 * The PITCH_SHIFTER_ settings below (samples at 48 kHz):
 * BUFFER_SIZE        the delay line: 1024 samples = 21.3 ms at 48 kHz, more
 *                    than the longest delay used (32 + 256 = 288 samples)
 * GRAIN_SAMPLES      the range a read head's delay sweeps before it jumps to
 *                    the other end: 256 samples = 5.3 ms
 * MIN_DELAY_SAMPLES  a read head stays at least 32 samples (0.7 ms) behind
 *                    the newest sample
 * MIN_RATIO, MAX_RATIO  one octave down (x0.5) to one octave up (x2);
 *                    PitchShifter_SetRatio refuses anything outside
 */
#define PITCH_SHIFTER_BUFFER_SIZE       1024U
#define PITCH_SHIFTER_GRAIN_SAMPLES     256.0f
#define PITCH_SHIFTER_MIN_DELAY_SAMPLES 32.0f
#define PITCH_SHIFTER_MIN_RATIO         0.50f
#define PITCH_SHIFTER_MAX_RATIO         2.00f

/** Persistent state for the dual-read-head granular pitch shifter. */
typedef struct
{
    float delay_buffer[PITCH_SHIFTER_BUFFER_SIZE];   /* the newest 1024 input samples, circular */
    uint16_t write_index;                            /* where the next input sample goes */
    float phase;            /* 0..1: how far head 1 is through its grain (head 2 is half a grain on) */
    float current_ratio;    /* the ratio in use now: it glides towards target_ratio */
    float target_ratio;     /* the ratio asked for with PitchShifter_SetRatio */
    bool hard_tune;         /* true (Autotune only): no glide and no dry blend, see PitchShifter_SetHardTune */
    float dry_mix;          /* hard tune only: share of the dry input, 1 while the ratio is released (exactly 1) */
} PitchShifter;

/**
 * @brief Initialise a pitch shifter to unity ratio and empty history.
 * @param shifter Shifter state. NULL is safely ignored.
 */
void PitchShifter_Init(PitchShifter *shifter);

/**
 * @brief Clear the delay line and restore unity pitch ratio.
 * @param shifter Shifter state. NULL is safely ignored.
 */
void PitchShifter_Reset(PitchShifter *shifter);

/**
 * @brief Set the desired pitch ratio for subsequent processing.
 * @param shifter Persistent shifter state.
 * @param ratio Pitch multiplier within PITCH_SHIFTER_MIN/MAX_RATIO.
 * @return true when accepted, false for NULL/non-finite/out-of-range input.
 */
bool PitchShifter_SetRatio(PitchShifter *shifter, float ratio);

/**
 * @brief Switch hard-tune mode on or off (Reset switches it off).
 *        Off (Pitch up, Pitch down): the ratio glides to a new value over
 *        about 21 ms, and near ratio 1 the dry input is blended back in.
 *        On (Autotune): a new ratio is used at once, and the output is
 *        the shifted sound, so the voice jumps cleanly from note to note.
 *        Only when the ratio is released to exactly 1 (no voice for a
 *        while) does the output fade to the dry input, over about 10 ms.
 * @param shifter Shifter state. NULL is safely ignored.
 * @param hard_tune true to switch it on.
 */
void PitchShifter_SetHardTune(PitchShifter *shifter, bool hard_tune);

/**
 * @brief Process signed 16-bit PCM through the granular pitch shifter.
 * @param shifter Persistent shifter state.
 * @param input Input samples.
 * @param output Output samples.
 * @param sample_count Number of samples; must be greater than zero.
 * @return true on success, false for invalid pointers/length.
 */
bool PitchShifter_ProcessBlock(PitchShifter *shifter,
                               const int16_t *input,
                               int16_t *output,
                               size_t sample_count);

#endif
